templates.template:
for ${i} in range(${rows}):
    for ${j} in range(${cols}):
        ${cursor}

class ${Plant}:
    """A plant with a name and a height."""

    def __init__(self, name, height=0.0):
        self.name = name
        self.height = height

    def __repr__(self):
        return f"${Plant}(name={self.name!r}, height={self.height})"

    def grow(self, amount):
        self.height += amount


plant = ${Plant}("Polytrichum", 10)
plant.grow(2)
print(plant)

from dataclasses import dataclass, field
@dataclass class ${Measurement}: name: str value: float = 0.0 tags: list = field(default_factory=list)
m = ${Measurement}("height", 12.5) print(m)

try:
    ${cursor}
except ${Exception} as e:
    print(f"Error: {e}")
else:
    pass
finally:
    pass

with open("${file}.txt", encoding="utf-8") as f:
    for line in f:
        print(line.rstrip())

